/**
 * Build Tranche Offsets
 * - Consolidates research from upstream nodes
 * - Emits 3 items (offsetDays: 0, 10, 20)
 * - Added 'post type' field from Start node
 */

const MAX_CHARS = 6000;
const SEP = "\n—\n";

// ---------- Helpers ----------

// 1. Define compactText FIRST so other helpers can use it if needed
function compactText(s, max = MAX_CHARS) {
  if (!s) return '';
  let out = String(s).replace(/\s+\n/g, '\n').replace(/\n{3,}/g, '\n\n').trim();
  if (out.length > max) out = out.slice(0, max) + '…';
  return out;
}

// 2. safeJoin (safe to use now)
function safeJoin(arr, key, max = MAX_CHARS) {
  if (!Array.isArray(arr)) return '';
  const parts = arr
    .map(o => (key ? (o?.[key] ?? '') : (typeof o === 'string' ? o : JSON.stringify(o))))
    .filter(Boolean);
  let out = parts.join(SEP);
  if (out.length > max) out = out.slice(0, max) + '…';
  return out;
}

function tryItems(nodeName) {
  try {
    const arr = $items(nodeName);
    if (Array.isArray(arr) && arr.length) return arr.map(i => i.json || {});
  } catch (e) { /* ignore */ }
  try {
    const j = $item(0).$node?.[nodeName]?.json;
    if (j) return [j];
  } catch (e) { /* ignore */ }
  return [];
}

function pickFirstNonEmpty(objs, key) {
  for (const o of objs) {
    const v = o?.[key];
    if (typeof v === 'string' && v.trim()) return v.trim();
  }
  return '';
}

// ---------- Gather upstream research ----------
const biz = tryItems('Get Bussines Research');
const comp = tryItems('Get Competitor Research');
const agg  = tryItems('Aggregate2');
const trend = tryItems('Get Trend Research');
const market = tryItems('Get Market Research');

// Business
const businessSummary = compactText(
  pickFirstNonEmpty(biz, 'Business Research Ideas Summary') ||
  pickFirstNonEmpty(biz, 'Business Research Ideas Summary\n')
);

const businessTone = compactText(
  pickFirstNonEmpty(biz, 'Social Media Tone/Voice/Language')
);

// Competitors
let competitorsWhy = '';
let competitorsTrends = '';

if (agg.length) {
  const a0 = agg[0];
  const why = Array.isArray(a0['Why this post worked: ']) ? a0['Why this post worked: '] : [a0['Why this post worked: ']].filter(Boolean);
  const trends = Array.isArray(a0['Trends Used: ']) ? a0['Trends Used: '] : [a0['Trends Used: ']].filter(Boolean);

  competitorsWhy = compactText(why.join(SEP));
  competitorsTrends = compactText(trends.join(SEP));
}

if (!competitorsWhy) {
  competitorsWhy = compactText(safeJoin(comp, 'Why this post worked: '));
}
if (!competitorsTrends) {
  competitorsTrends = compactText(safeJoin(comp, 'Trends Used: '));
}

// Trend research
const trendHashtags = compactText(
  pickFirstNonEmpty(trend, 'Hashtags') ||
  pickFirstNonEmpty(trend, 'Hashtag') ||
  pickFirstNonEmpty(trend, 'Trend Hashtags')
);

const trendNotes = compactText(
  pickFirstNonEmpty(trend, 'Key Takeaways & Content Calendar Recommendations:') ||
  pickFirstNonEmpty(trend, 'Chat GPT Trend Search') ||
  pickFirstNonEmpty(trend, 'Trend or Pattern')
);

// Market research
let marketSummary = '';
if (market.length) {
  const m0 = { ...market[0] };
  ['row_number', 'Client ID', 'Run ID', 'isTest', 'writeKey', '#', 'Link to post'].forEach(k => delete m0[k]);
  const pretty = Object.entries(m0)
    .filter(([, v]) => v !== '' && v !== null && v !== undefined)
    .map(([k, v]) => `${k}: ${typeof v === 'string' ? v : JSON.stringify(v)}`)
    .join('\n');
  marketSummary = compactText(pretty || JSON.stringify(m0));
}

// ---------- Read context & post type from Start ----------
let bussinesContext = '';
let postType = '';

try {
  const startNode = $('Start').first().json;
  bussinesContext = compactText(startNode?.['bussines context'] || '');
  postType = compactText(startNode?.['post type'] || '');
} catch (e) {
  // Fallback
  const startNode = $item(0).$node?.Start?.json;
  bussinesContext = compactText(startNode?.['bussines context'] || '');
  postType = compactText(startNode?.['post type'] || '');
}

// ---------- Emit three tranche items: 0, 10, 20 days ----------
const trancheOffsets = [0, 10, 20];
const base = {
  businessSummary,
  businessTone,
  competitorsWhy,
  competitorsTrends,
  trendHashtags,
  trendNotes,
  marketSummary,
  postType,
  ['bussines context']: bussinesContext,
};

// Propagate pass-through fields
const startJson = $item(0).$node?.Start?.json || {};
['clientId', 'isTest', 'sheetDocId', 'writeKey'].forEach(k => {
  if (startJson[k] !== undefined) base[k] = startJson[k];
});

const out = trancheOffsets.map(offsetDays => ({
  json: { offsetDays, ...base }
}));

return out;

